Below is a step-by-step guide to creating a complete React shopping cart component with state management using Redux Toolkit. This example will cover the main functionality of a cart, including adding an item, removing an item, and calculating the total cost.

### Step 1: Setting Up Redux Toolkit and Redux

First, ensure you have `@reduxjs/toolkit` installed in your project:

```bash
npm install @reduxjs/toolkit
```

### Step 2: Cart Slice Redux Store Configuration

Create a new file named `cartSlice.ts` in your Redux store slices directory (e.g., `reducer/cartSlice.ts`):

```tsx
import { createSlice } from '@reduxjs/toolkit';
import { RootState } from '../rootReducer';

interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
}

const initialCartState: CartItem[] = [
  // Example items
  { id: '1', name: 'Product 1', price: 10, quantity: 0 },
  { id: '2', name: 'Product 2', price: 20, quantity: 0 },
];

const cartSlice = createSlice({
  name: 'cart',
  initialState: {
    items: initialCartState,
  },
  reducers: {
    addItem(state, action) {
      const item = action.payload;
      const found = state.items.find((i) => i.id === item.id);
      if (found) {
        found.quantity++;
      } else {
        state.items.push({...item, quantity: 1 });
      }
    },
    removeItem(state, action) {
      const id = action.payload;
      state.items = state.items.filter((i) => i.id!== id);
    },
    adjustQuantity(state, action) {
      const id = action.payload.id;
      const item = state.items.find((i) => i.id === id);
      if (item && action.payload.quantity > 0) {
        item.quantity = action.payload.quantity;
      }
    },
  },
});

export const { addItem, removeItem, adjustQuantity } = cartSlice.actions;
export default cartSlice.reducer;
```

This slice defines functions for adding items to the cart, removing items, and adjusting the quantity of items.

