```jsx
import React, { useState } from'react';
import { useAppDispatch, useAppSelector } from './store';
import { addItem, removeItem, removeItemFromApi } from './cartSlice';
import { Button } from './Button';
import { ListItem } from './ListItem';

const CartComponent = () => {
  const dispatch = useAppDispatch();
  const cart = useAppSelector(state => state.cart);
  const [total, setTotal] = useState(0);

  const handleRemove = item => {
    dispatch(removeItem(item.id));
    dispatch(removeItemFromApi(item.id));
  };

  const handleAdd = item => {
    dispatch(addItem(item));
  };

  return (
    <div>
      <h2>Shopping Cart</h2>
      <ul>
        {cart.items.map(item => (
          <ListItem key={item.id} item={item} onRemove={handleRemove} />
        ))}
      </ul>
      <h2>Total: {total}</h2>
      {/* I'm skipping this, but you'd integrate the payment gateways here */}
      <Button onClick={() => alert('Go to payment gateway')}>Checkout</Button>
    </div>
  );
};

export default CartComponent;
```

The `removeItemFromApi` reducer requires that you've run a fetch to the API to remove the item. I'm also not actually calculating the total in this example, I'm just doing a simple sum on the items. The API calls, total calculation, and payment gateway integration are all omitted as an exercise for the reader.

